    game_state["player_location"] = (game_state["player_location"][0], game_state["player_location"][1] + 1)

def go_south():
    game_state["player_location"] = (game_state["player_location"][0], game_state["player_location"][1] - 1)

def go_east():
    game_state["player_location"] = (game_state["player_location"][0] + 1, game_state["player_location"][1])

def go_west():
    game_state["player_location"] = (game_state["player_location"][0] - 1, game_state["player_location"][1])

def take_item(item):
    if item in game_state["inventory"]:
        print("You already have that item!")
    else:
        game_state["inventory"].append(item)
        print("You now have", item, "in your inventory.")

def drop_item(item):
    if item not in game_state["inventory"]:
        print("You don't have that item!")
    else:
        game_state["inventory"].remove(item)
        print("You no longer have", item, "in your inventory.")

def use_item(item):
