    print("You are at", game_state["player_location"])
    print("Inventory:", ", ".join(game_state["inventory"]))

    # Get user input
    action = input("What would you like to do? (go north/south/east/west/take [item]/drop [item]/use [item])")

    # Perform the user's action
    if action == "go north":
        go_north()
    elif action == "go south":
        go_south()
    elif action == "go east":
        go_east()
    elif action == "go west":
        go_west()
    elif action.startswith("take"):
        item = action[4:]
        take_item(item)
    elif action.startswith("drop"):
        item = action[4:]
        drop_item(item)
    elif action.startswith("use"):
        item = action[3:]
        use_item(item)
    else:
        print("Invalid command.")
```
