[C++]
#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

void getUniqueElements(vector<int>& myList) {
    // Create a set to store unique elements
    set<int> uniqueElements;

    // Iterate through the list and add each element to the set
    for (int i = 0; i < myList.size(); i++) {
        uniqueElements.insert(myList[i]);
    }

    // Store the unique elements in a vector
    vector<int> uniqueVector(uniqueElements.begin(), uniqueElements.end());

    // Print the unique elements
    for (int i = 0; i < uniqueVector.size(); i++) {
        cout << uniqueVector[i] << " ";
    }
    cout << endl;
}

void sortElements(vector<int>& myList) {
    // Sort the list in ascending order using sort() function
    sort(myList.begin(), myList.end());

    // Print the sorted list
    for (int i = 0; i < myList.size(); i++) {
        cout << myList[i] << " ";
    }
    cout << endl;
}

void concatenateElements(vector<int>& myList1, vector<int>& myList2) {
    // Concatenate the two lists using the operator+
    vector<int> concatList = myList1 + myList2;

    // Print the concatenated list
    for (int i = 0; i < concatList.size(); i++) {
        cout << concatList[i] << " ";
    }
    cout << endl;
}

void getDuplicateElements(vector<int>& myList) {
    // Create a set to store duplicate elements
    set<int> duplicateElements;

    // Iterate through the list and check if each element is already in the set
    for (int i = 0; i < myList.size(); i++) {
        if (duplicateElements.find(myList[i]) != duplicateElements.end()) {
            cout << myList[i] << " ";
        } else {
            duplicateElements.insert(myList[i]);
        }
    }
    cout << endl;
}

void getUniqueElementsAndCounts(vector<int>& myList) {
    // Create a map to store the counts of each unique element
    map<int, int> uniqueElementsCounts;

    // Iterate through the list and increment the count for each unique element
    for (int i = 0; i < myList.size(); i++) {
        auto it = uniqueElementsCounts.find(myList[i]);
        if (it != uniqueElementsCounts.end()) {
            it->second++;
        } else {
            uniqueElementsCounts[myList[i]] = 1;
        }
    }

    // Print the unique elements and their counts
    for (const auto& elem : uniqueElementsCounts) {
        cout << elem.first << " " << elem.second << endl;
    }
}

int main() {
    vector<int> myList = {1, 2, 3, 4, 5, 6};

    getUniqueElements(myList);
    sortElements(myList);
    concatenateElements(myList, myList);
    getDuplicateElements(myList);
    getUniqueElementsAndCounts(myList);

    return 0;
}
[/C++]

[C#]
using System;
using System.Collections.Generic;
using System.Linq;

class Program
{
    static void Main(string[] args)
    {
        // Initialize a list of integers
        List<int> myList = new List<int>() { 1, 2, 3, 4, 5, 6 };

        // Get the unique elements in the list using LINQ
        var uniqueElements = myList.Distinct().ToList();
        Console.WriteLine(string.Join(", ", uniqueElements));

        // Sort the list and print it
        myList.Sort();
        Console.WriteLine(string.Join(", ", myList));

        // Concatenate two lists using LINQ
        var concatenatedList = myList.Concat(myList).ToList();
        Console.WriteLine(string.Join(", ", concatenatedList));

        // Get the duplicate elements in the list using LINQ
        var duplicateElements = myList.GroupBy(x => x).Where(g => g.Count() > 1).Select(x => x.Key);
        Console.WriteLine(string.Join(", ", duplicateElements));

        // Get the unique elements and their counts in the list using LINQ
        var uniqueElementCounts = myList.GroupBy(x => x).Select(g => new { g.Key, Count = g.Count() });
        foreach (var element in uniqueElementCounts)
        {
            Console.WriteLine($"{element.Key} - {element.Count}");
        }
    }
}
[/C#]

[JAVA]
import java.util.*;

public class Main {
    public static void main(String[] args) {
        // Initialize a list of integers
        List<Integer> myList = new ArrayList<>(Arrays.asList(1, 2, 3, 4, 5, 6));

        // Get the unique elements in the list using a stream
        List<Integer> uniqueElements = myList.stream().distinct().collect(Collectors.toList());
        System.out.println(uniqueElements);

        // Sort the list and print it
        myList.sort((a, b) -> a - b);
        System.out.println(myList);

        // Concatenate two lists using streams
        List<Integer> concatenatedList = Stream.concat(myList.stream(), myList.stream()).collect(Collectors.toList());
        System.out.println(concatenatedList);

        // Get the duplicate elements in the list using a stream
        List<Integer> duplicateElements = myList.stream().filter(i -> Collections.frequency(myList, i) > 1).collect(Collectors.toList());
        System.out.println(duplicateElements);

        // Get the unique elements and their counts in the list using a stream
        List<Map.Entry<Integer, Long>> uniqueElementCounts = myList.stream().collect(Collectors.groupingBy(Function.identity(), Collectors.counting()));
        uniqueElementCounts.forEach(entry -> System.out.println(entry.getKey() + " - " + entry.getValue()));
    }
}
