The Go version of this code would be:
```go
package main

import (
    "fmt"
)

func largestSmallestIntegers(lst []int) (a, b, c, d int) {
    if len(lst) == 0 {
        return
    }

    allNegative := make([]int, 0, len(lst))
    allNonNegative := make([]int, 0, len(lst))

    for _, num := range lst {
        if num < 0 {
            allNegative = append(allNegative, num)
        } else {
            allNonNegative = append(allNonNegative, num)
        }
    }

    negativeEven := make([]int, 0, len(lst))
    negativeOdd := make([]int, 0, len(lst))
    nonNegativeEven := make([]int, 0, len(lst))
    nonNegativeOdd := make([]int, 0, len(lst))

    for _, num := range allNegative {
        if num%2 == 0 {
            negativeEven = append(negativeEven, num)
        } else {
            negativeOdd = append(negativeOdd, num)
        }
    }

    for _, num := range allNonNegative {
        if num%2 == 0 {
            nonNegativeEven = append(nonNegativeEven, num)
        } else {
            nonNegativeOdd = append(nonNegativeOdd, num)
        }
    }

    a = max(negativeEven...)
    b = min(nonNegativeEven...)
    c = max(negativeOdd...)
    d = min(nonNegativeOdd...)

    return
}

func main() {
    lst := []int{2, -4, 1, 3, 5, 7}
    a, b, c, d := largestSmallestIntegers(lst)
    fmt.Println(a, b, c, d)

    lst = []int{}
    a, b, c, d = largestSmallestIntegers(lst)
    fmt.Println(a, b, c, d)

    lst = []int{0, -1}
    a, b, c, d = largestSmallestIntegers(lst)
    fmt.Println(a, b, c, d)
}
```
