def enhanced_char_count(s):
    """
    This function, 'enhanced_char_count', takes a word in string format and returns a dictionary displaying the counts and frequencies of letters, digits, and special characters plus the highest and lowest frequency characters.

    Example:
    >>> enhanced_char_count("a1b2c3d4e")
    {'Letters': {'Vowels': {'a': 1, 'e': 1}, 'Consonants': {'b': 1, 'c': 1, 'd': 1}}, 'Digits': {'1': 1, '2': 1, '3': 1, '4': 1}, 'Special characters': 0, 'Highest frequency': {'a': 1}, 'Lowest frequency': {'b': 1, 'c': 1, 'd': 1, 'e': 1}}
    """

    # Initialize a dictionary to store the counts and frequencies
    char_counts = {}

    # Iterate through the word and count the number of vowels, consonants, digits, and special characters
    for char in s:
        if char.isalpha():
            if char.islower():
                if char in char_counts:
                    char_counts[char] += 1
                else:
                    char_counts[char] = 1
            else:
                if "Capital letters" in char_counts:
                    char_counts["Capital letters"] += 1
                else:
                    char_counts["Capital letters"] = 1
        elif char.isdigit():
            if char in char_counts:
                char_counts[char] += 1
            else:
                char_counts[char] = 1
        else:
            if "Special characters" in char_counts:
                char_counts["Special characters"] += 1
            else:
                char_counts["Special characters"] = 1

    # Calculate the frequency of each vowel and consonant
    for key, value in char_counts.items():
        if key in "aeiouAEIOU":
            char_counts[key] = round(value / len(s) * 100, 2)
        else:
            char_counts[key] = round(value / len(s) * 100, 2)

    # Find the highest and lowest frequency characters
    highest_freq = {}
    lowest_freq = {}
    for key, value in char_counts.items():
        if "Highest frequency" in highest_freq:
            if value > highest_freq["Highest frequency"]:
                highest_freq[key] = value
        else:
            highest_freq[key] = value
    for key, value in char_counts.items():
        if "Lowest frequency" in lowest_freq:
            if value < lowest_freq["Lowest frequency"]:
                lowest_freq[key] = value
        else:
            lowest_freq[key] = value

    # Categorize characters into letters, digits, and special characters
    letter_counts = {}
    digit_counts = {}
    special_char_counts = {}
    for key, value in char_counts.items():
        if key.isalpha():
            if "Letters" not in letter_counts:
                letter_counts["Letters"] = {}
            if key.islower():
                if "Vowels" not in letter_counts["Letters"]:
                    letter_counts["Letters"]["Vowels"] = {}
                if key in letter_counts["Letters"]["Vowels"]:
                    letter_counts["Letters"]["Vowels"][key] += value
                else:
                    letter_counts["Letters"]["Vowels"][key] = value
            else:
                if "Consonants" not in letter_counts["Letters"]:
                    letter_counts["Letters"]["Consonants"] = {}
                if key in letter_counts["Letters"]["Consonants"]:
                    letter_counts["Letters"]["Consonants"][key] += value
                else:
                    letter_counts["Letters"]["Consonants"][key] = value
        elif key.isdigit():
            if "Digits" not in digit_counts:
                digit_counts["Digits"] = {}
            if key in digit_counts["Digits"]:
                digit_counts["Digits"][key] += value
            else:
                digit_counts["Digits"][key] = value
        else:
            if "Special characters" not in special_char_counts:
                special_char_counts["Special characters"] = {}
            if key in special_char_counts["Special characters"]:
                special_char_counts["Special characters"][key] += value
            else:
                special_char_counts["Special characters"][key] = value

    # Combine the counts and frequencies into a single dictionary
    enhanced_char_counts = {**letter_counts, **digit_counts, **special_char_counts}
    enhanced_char_counts["Highest frequency"] = highest_freq
    enhanced_char_counts["Lowest frequency"] = lowest_freq

    return enhanced_char_counts

