class Person:
    def __init__(self, attributes):
        self.attributes = attributes

    def get_attribute(self, attribute_name):
        return self.attributes[attribute_name]

    def set_attribute(self, attribute_name, value):
        self.attributes[attribute_name] = value

    def update_attributes(self, attributes):
        for attribute_name, value in attributes.items():
            if isinstance(value, dict):
                nested_object = Person(value)
                self.set_attribute(attribute_name, nested_object)
            else:
                self.set_attribute(attribute_name, value)

    def get_nested_attribute(self, attribute_path):
        nested_object = self
        for attribute_name in attribute_path.split('.'):
            nested_object = nested_object.get_attribute(attribute_name)
        return nested_object

    def set_nested_attribute(self, attribute_path, value):
        nested_object = self
        for attribute_name in attribute_path.split('.'):
            if isinstance(value, dict):
                nested_object = nested_object.get_nested_attribute(attribute_name)
            else:
                nested_object.set_attribute(attribute_name, value)

