```
def reverse_sentence(sentence):
    words = sentence.split()
    reversed_words = []
    for word in words:
        rev_word = ""
        for letter in range(len(word)-1, -1, -1):
            rev_word += word[letter]
        reversed_words.append(rev_word)
    return " ".join(reversed_words)

def reverse_sentence_with_vowels(sentence):
    words = sentence.split()
    reversed_words = []
    for word in words:
        rev_word = ""
        vowel_flag = False
        for letter in range(len(word)-1, -1, -1):
            if word[letter] in "aeiou":
                vowel_flag = True
            if vowel_flag:
                rev_word += word[letter]
        reversed_words.append(rev_word)
    return " ".join(reversed_words)
```
