// Define a function to check if a number is prime
function isPrime(n) {
  // If the number is less than 2, it is not prime
  if (n < 2) return false;

  // Check if the number is divisible by any of the first two factors
  for (let i = 2; i * i <= n; i++) {
    if (n % i === 0) return false;
  }

  // If the number is not divisible by any of the first two factors, it is prime
  return true;
}
```
This version of the code is more efficient because it only checks divisibility for the first two factors. This reduces the number of unnecessary comparisons and makes the function faster and more scalable.

