Here is an example of how you can implement a generic repository pattern in C#:
```
public interface IRepository<T> where T : class
{
    Task<T> GetByIdAsync(int id);
    Task<IEnumerable<T>> GetAllAsync();
    Task AddAsync(T entity);
    Task UpdateAsync(T entity);
    Task DeleteAsync(int id);
}
```
And here is an example of how you can implement the `ProductRepository` class that implements the `IRepository<Product>` interface:
```
public class ProductRepository : IRepository<Product>
{
    private readonly DbContext _context;

    public ProductRepository(DbContext context)
    {
        _context = context;
    }

    public async Task<IEnumerable<Product>> GetAllAsync()
    {
        return await _context.Products.ToListAsync();
    }

    public async Task<Product> GetByIdAsync(int id)
    {
        return await _context.Products.FindAsync(id);
    }

    public async Task AddAsync(Product entity)
    {
        await _context.Products.AddAsync(entity);
        await _context.SaveChangesAsync();
    }

    public async Task UpdateAsync(Product entity)
    {
        var product = await GetByIdAsync(entity.Id);
        if (product != null)
        {
            product.Name = entity.Name;
            product.Price = entity.Price;
            // ...
            await _context.SaveChangesAsync();
        }
    }

    public async Task DeleteAsync(int id)
    {
        var product = await GetByIdAsync(id);
        if (product != null)
        {
            _context.Products.Remove(product);
            await _context.SaveChangesAsync();
        }
    }
}
```
You can then use the `ProductRepository` class to perform CRUD operations on the `Product` entity, for example:
```
var repository = new ProductRepository(_context);

// Get all products
var products = await repository.GetAllAsync();

// Get a product by ID
var product = await repository.GetByIdAsync(123);

// Add a new product
await repository.AddAsync(new Product { Id = 456, Name = "Product 4", Price = 9.99 });

// Update an existing product
await repository.UpdateAsync(new Product { Id = 789, Name = "Product 7", Price = 19.99 });

// Delete a product
await repository.DeleteAsync(789);
```

