def multiply_list(input_list, input_number):
    # Check if the input list is valid
    if not isinstance(input_list, list) or len(input_list) > 1000:
        raise ValueError("Invalid input list")

    # Check if the input number is valid
    if not isinstance(input_number, (int, float)) or input_number == 0:
        raise ValueError("Invalid input number")

    # Handle negative numbers
    if input_number < 0:
        input_number = abs(input_number)

    # Multiply all elements in the list by the input number
    output_list = []
    for element in input_list:
        if isinstance(element, int):
            output_list.append(element * input_number)
        else:
            output_list.append(float(element) * input_number)

    return output_list

