import math

def mahalanobis_distance(data_points, test_point):
    # Calculate the covariance matrix
    covariance_matrix = calculate_covariance_matrix(data_points)

    # Calculate the inverse of the covariance matrix
    try:
        inverse_covariance_matrix = invert_matrix(covariance_matrix)
    except ValueError:
        add_constant_to_diagonal(covariance_matrix, 0.0001)
        inverse_covariance_matrix = invert_matrix(covariance_matrix)

    # Calculate the difference vector between the test point and the mean of the distribution
    difference_vector = calculate_difference_vector(test_point, get_mean(data_points))

    # Calculate the transpose of the difference vector
    transposed_difference_vector = transpose_vector(difference_vector)

    # Multiply the difference vector with the inverse of the covariance matrix
    product_matrix = multiply_matrices(inverse_covariance_matrix, transposed_difference_vector)

    # Calculate the dot product of the result with the difference vector
    dot_product = calculate_dot_product(product_matrix, difference_vector)

    # Take the square root of the dot product to get the Mahalanobis distance
    mahalanobis_distance = math.sqrt(dot_product)

    return mahalanobis_distance

def calculate_covariance_matrix(data_points):
    # Initialize the covariance matrix as a dictionary of dictionaries
    covariance_matrix = {}

    # Calculate the mean of each variable (coordinate)
    means = get_mean(data_points)

    # Calculate the sum of the products of the differences between the variable values and their respective means
    for i in range(len(data_points[0])):
        covariance_matrix[i] = {}
        for j in range(i, len(data_points[0])):
            covariance_matrix[i][j] = 0
            for data_point in data_points:
                covariance_matrix[i][j] += (data_point[i] - means[i]) * (data_point[j] - means[j])

    # Divide the sum of the products by the total number of data points minus 1
    num_data_points = len(data_points)
    for i in range(len(data_points[0])):
        for j in range(i, len(data_points[0])):
            covariance_matrix[i][j] /= (num_data_points - 1)

    return covariance_matrix

def get_mean(data_points):
    # Initialize the mean as a dictionary of zeros
    means = {}
    for i in range(len(data_points[0])):
        means[i] = 0

    # Calculate the sum of each variable (coordinate)
    for data_point in data_points:
        for i in range(len(data_points[0])):
            means[i] += data_point[i]

    # Divide the sum by the total number of data points
    num_data_points = len(data_points)
    for i in range(len(data_points[0])):
        means[i] /= num_data_points

    return means

def calculate_difference_vector(test_point, mean):
    # Initialize the difference vector as a dictionary of zeros
    difference_vector = {}
    for i in range(len(mean)):
        difference_vector[i] = 0

    # Calculate the differences between the test point and the mean
    for i in range(len(test_point)):
        difference_vector[i] = test_point[i] - mean[i]

    return difference_vector

def transpose_vector(vector):
    # Initialize the transposed vector as a dictionary of zeros
    transposed_vector = {}
    for key in vector:
        transposed_vector[key] = 0

    # Calculate the dot product of the vector and itself to get the transposed vector
    for i in range(len(vector)):
        for j in range(i, len(vector)):
            transposed_vector[j] += vector[i] * vector[j]

    return transposed_vector

def multiply_matrices(matrix1, matrix2):
    # Initialize the product matrix as a dictionary of dictionaries
    product_matrix = {}

    # Calculate the dot product of each element of the matrices to get the product matrix
    for i in range(len(matrix1)):
        product_matrix[i] = {}
        for j in range(len(matrix2[0])):
            product_matrix[i][j] = 0
            for k in range(len(matrix2)):
                product_matrix[i][j] += matrix1[i][k] * matrix2[k][j]

    return product_matrix

def calculate_dot_product(vector1, vector2):
    # Initialize the dot product as 0
    dot_product = 0

    # Calculate the dot product of the vectors by summing up the products of their corresponding elements
    for i in range(len(vector1)):
        dot_product += vector1[i] * vector2[i]

    return dot_product

def invert_matrix(matrix):
    # Initialize the inverse matrix as a dictionary of dictionaries
    inverse_matrix = {}

    # Calculate the determinant of the matrix
    determinant = calculate_determinant(matrix)

    # Check if the determinant is 0, indicating that the matrix is not invertible
    if determinant == 0:
        raise ValueError("The matrix is not invertible")

    # Calculate the inverse of each element of the matrix using Cramer's rule
    for i in range(len(matrix)):
        inverse_matrix[i] = {}
        for j in range(len(matrix[0])):
            inverse_matrix[i][j] = determinant * calculate_cofactor(matrix, i, j) / determinant

    return inverse_matrix

def calculate_determinant(matrix):
    # Calculate the determinant of a 2x2 matrix by hand
    if len(matrix) == 2:
        return matrix[0][0] * matrix[1][1] - matrix[0][1] * matrix[1][0]

    # Initialize the determinant as 0 and calculate the sum of the products of the cofactors of each element of the matrix
    determinant = 0
    for i in range(len(matrix)):
        determinant += Math.pow(-1, i) * matrix[0][i] * calculate_determinant(get_minor(matrix, 0, i))

    return determinant

def get_cofactor(matrix, row, col):
    # Initialize the cofactor as a dictionary of zeros
    cofactor = {}
    for i in range(len(matrix)):
        cofactor[i] = {}
        for j in range(len(matrix[0])):
            if i < row and j < col:
                cofactor[i][j] = matrix[i][j]
            elif i < row and j > col:
                cofactor[i][j] = -matrix[i][j]
            elif i > row and j < col:
                cofactor[i][j] = -matrix[i][j]
            elif i > row and j > col:
                cofactor[i][j] = matrix[i][j]

    return cofactor

def calculate_cofactor(matrix, row, col):
    # Calculate the cofactor of a 2x2 matrix by hand
    if len(matrix) == 2:
        return matrix[0][0] * matrix[1][1] - matrix[0][1] * matrix[1][0]

    # Initialize the cofactor as 0 and calculate the sum of the products of the cofactors of each element of the minor
    cofactor = 0
    for i in range(len(matrix)):
        if i < row:
            cofactor += Math.pow(-1, i) * matrix[i][col] * calculate_cofactor(get_minor(matrix, 0, col), i, col)
        elif i > row:
            cofactor += -Math.pow(-1, i) * matrix[i][col] * calculate_cofactor(get_minor(matrix, 0, col), i, col)

    return cofactor

def get_minor(matrix, row, col):
    # Initialize the minor as a dictionary of zeros
    minor = {}
    for i in range(len(matrix)):
        if i < row:
            minor[i] = {}
            for j in range(col):
                minor[i][j] = matrix[i][j]
        elif i > row:
            minor[i] = {}
            for j in range(len(matrix[0])):
                if j < col:
                    minor[i][j] = matrix[i][j]
                elif j > col:
                    minor[i][j] = matrix[i][j + 1]

    return minor

def add_matrices(matrix1, matrix2):
    # Initialize the sum as a dictionary of dictionaries
    sum = {}

    # Calculate the sum of each element of the matrices by adding their corresponding elements
    for i in range(len(matrix1)):
        sum[i] = {}
        for j in range(len(matrix2[0])):
            sum[i][j] = matrix1[i][j] + matrix2[i][j]

    return sum

def subtract_matrices(matrix1, matrix2):
    # Initialize the difference as a dictionary of dictionaries
    difference = {}

    # Calculate the difference of each element of the matrices by subtracting their corresponding elements
    for i in range(len(matrix1)):
        difference[i] = {}
        for j in range(len(matrix2[0])):
            difference[i][j] = matrix1[i][j] - matrix2[i][j]

    return difference

def scalar_multiply(c, matrix):
    # Initialize the product as a dictionary of dictionaries
    product = {}

    # Calculate the product of each element of the matrix by multiplying it by a scalar
    for i in range(len(matrix)):
        product[i] = {}
        for j in range(len(matrix[0])):
            product[i][j] = c * matrix[i][j]

    return product

def transpose(matrix):
    # Initialize the transpose as a dictionary of dictionaries
    transposed = {}

    # Calculate the elements of the transpose by swapping the rows and columns of the matrix
    for i in range(len(matrix)):
        transposed[i] = {}
        for j in range(len(matrix[0])):
            transposed[j][i] = matrix[i][j]

    return transposed
```

### <a name="dot-product"></a>Dot product

The dot product, also known as the scalar product or inner product, is a way to multiply two vectors together. It takes two matrices with equal dimensions and returns a single value. For example:

| **A** | **B** | **A ⋅ B** |
| --- | --- | --- |
| 1 | 2 | 2 |
| 3 | 4 | 10 |
| 5 | 6 | 18 |

The dot product of two vectors is calculated by multiplying corresponding elements and summing the products. The following Python code shows an implementation of the dot product:

```python
def dot(A, B):
    return sum(a * b for a, b in zip(A, B))
```

### <a name="norm"></a>Norm

The norm is a value that represents how big a vector is. The following Python code shows an implementation of the L2 norm:

```python
from math import sqrt

def norm(A):
    return sqrt(sum(x**2 for x in A))
```

### <a name="distance"></a>Distance

The distance between two points is how far apart they are. The following Python code shows an implementation of the Euclidean distance:

```python
from math import sqrt

def distance(A, B):
    return sqrt(sum((x - y)**2 for x, y in zip(A, B)))
```

