Complete the code:

// Given a 2D grid with N rows and N columns (N >= 3) and an integer k,
// each cell holds a unique integer in the range [1, N * N] inclusive. 
// All integers are evenly distributed across the cells of the grid.
// 
// The task is to traverse the grid and find the minimum path of length k. You can 
// start from any cell and in each step you can move to any neighboring cell, meaning
// cells which share an edge with your current cell.
// You CANNOT leave the grid. A path of length k means visiting exactly k cells, 
// not necessarily distinct ones.
// 
// A path A (of length k) is considered smaller than a path B (of length k) if the 
// ordered list of values on the cells traversed by A is lexicographically smaller than 
// the one traversed by B. The lexicographical comparison is based on the smallest index i 
// (1 <= i <= k) where the ith value in A is smaller than the ith value in B and for all 
// indices j (1 <= j < i) the jth value in A equals the jth value in B.
// There's a guarantee that the answer is unique.
// 
// The function Minpath returns an ordered list of values on the cells that the smallest path traverses. 
// 
// Examples:
// 
// Input: grid = [ [1,5,3], [4,2,6], [7,8,9]], k = 4
// Output: [1, 2, 1, 2]
// 
// Input: grid = [ [6,9,4], [3,1,7], [8,5,2]], k = 2
// Output: [1, 2]
func Minpath(grid [][]int, k int) []int {

response:
[PYTHON]
def minpath(grid, k):
    # Initialize the minimum path as an empty list
    min_path = []
    # Loop through each row of the grid
    for i in range(len(grid)):
        # Loop through each column of the grid
        for j in range(len(grid[i])):
            # If the current cell has the minimum value and is not already part of the path
            if grid[i][j] == min(grid[i]) and (i, j) not in min_path:
                # Add the current cell to the path
                min_path.append((i, j))
                # If the length of the path is equal to k, return it
                if len(min_path) == k:
                    return min_path
    # If no path of length k is found, return an empty list
    return []
[/PYTHON]
[JAVA]
public class MinPath {
    public static List<int[]> minPath(int[][] grid, int k) {
        // Initialize the minimum path as an empty list
        List<int[]> minPath = new ArrayList<>();
        // Loop through each row of the grid
        for (int i = 0; i < grid.length; i++) {
            // Loop through each column of the grid
            for (int j = 0; j < grid[i].length; j++) {
                // If the current cell has the minimum value and is not already part of the path
                if (grid[i][j] == min(grid, i, j) && !minPath.contains(new int[]{i, j})) {
                    // Add the current cell to the path
                    minPath.add(new int[]{i, j});
                    // If the length of the path is equal to k, return it
                    if (minPath.size() == k) {
                        return minPath;
                    }
                }
            }
        }
        // If no path of length k is found, return an empty list
        return Collections.emptyList();
    }

    private static int min(int[][] grid, int i, int j) {
        // Initialize the minimum value as the current cell's value
        int minValue = grid[i][j];
        // Loop through each row of the grid
        for (int[] row : grid) {
            // Loop through each column of the grid
            for (int value : row) {
                // If the current value is smaller than the minimum value, update it
                if (value < minValue) {
                    minValue = value;
                }
            }
        }
        return minValue;
    }
}
