// Function to find the minimum path in a 2D grid
vector<vector<int>> minPath(vector<vector<int>>& grid, int k) {
    // Initialize the minimum path as an empty list
    vector<vector<int>> minPath;

    // Loop through each row of the grid
    for (int i = 0; i < grid.size(); i++) {
        // Loop through each column of the grid
        for (int j = 0; j < grid[i].size(); j++) {
            // If the current cell has the minimum value and is not already part of the path
            if (grid[i][j] == *min_element(begin(grid), end(grid)) && find(begin(minPath), end(minPath), vector<int>{i, j}) == end(minPath)) {
                // Add the current cell to the path
                minPath.push_back({i, j});
                // If the length of the path is equal to k, return it
                if (minPath.size() == k) {
                    return minPath;
                }
            }
        }
    }

    // If no path of length k is found, return an empty list
    return {};
}

