                *playerX -= 1;
                *playerY -= 1;
                return true;
            } else {
                return false;
            }
            break;
        case 'D':
            if (*playerY + 1 < GRID_SIZE) {
                *playerX += 1;
                *playerY += 1;
                return true;
            } else {
                return false;
            }
            break;
        case 'L':
