 * - $color1: The first color, which will be used as the base color for the gradient.
 * - $color2: The second color, which will be used as the end color for the gradient.
 */
@function gradient-colors($color1, $color2) {
  /*
   * This variable is used to calculate the difference between the two colors.
   */
  $diff: abs(red($color1) - red($color2));

  /*
   * If the difference between the two colors is greater than 0, we know that the colors are different.
   * In this case, we can calculate the gradient by iterating over the number of steps and generating a new color at each step.
   */
  @if $diff > 0 {
    /*
     * This variable is used to keep track of the current step in the iteration.
     */
    $step: 1;

    /*
     * This map is used to store the generated colors for the gradient.
     */
    $colors: ();

    @while $step <= 2 {
      /*
       * Calculate the current color based on the difference between the two colors and the step number.
       */
      $current-color: $color1 + ($diff * $step);

      /*
       * Add the current color to the map of generated colors.
       */
      $colors: append($colors, $current-color);

      /*
       * Increment the step number.
       */
      $step: $step + 1;
    }

    @return $colors;
  }

  /*
   * If the difference between the two colors is equal to 0, we know that the colors are identical.
   * In this case, we can return a single color as the gradient.
   */
