Construct a function that assesses whether a given string concludes with a defined substring. The function should additionally accommodate situations where the identical substring reoccurs at the ending of the string. Illustratively:
>>> has_suffix("activity", "ity")
True
>>> has_suffix("helloityity", "ity")
True
>>> has_suffix("heaven", "ity")
False
Initiate the code as:
#include<stdio.h>
#include<string>
using namespace std;
bool has_suffix(string str,string suffix){

response:
```
#include <iostream>
#include <string>

using namespace std;

bool has_suffix(const string& str, const string& suffix) {
    // Check if the substring is present at the end of the string
    if (str.size() >= suffix.size() &&
        str.compare(str.size() - suffix.size(), suffix.size(), suffix) == 0) {
        return true;
    }

    // If the substring is not present at the end of the string, check if it is
    // present at the end of the string and then iterate backwards until we find
    // a match or reach the beginning of the string
    for (int i = str.size() - suffix.size(); i >= 0; i--) {
        if (str.compare(i, suffix.size(), suffix) == 0) {
            return true;
        }
    }

    // If we reach this point, then the substring was not found in the string
    return false;
}

int main() {
    cout << has_suffix("activity", "ity") << endl;  // True
    cout << has_suffix("helloityity", "ity") << endl;  // True
    cout << has_suffix("heaven", "ity") << endl;  // False

    return 0;
}
```
