Here's an example of how to create a secure and scalable REST API in Node.js with authentication, rate limiting, support for pagination and sorting:

1. Install the necessary dependencies:
```bash
npm install express-rate-limit express-brute-mongoose mongoose
```
2. Create a new file called `api.js` and define your API routes in it:
```javascript
const express = require('express');
const app = express();
const bodyParser = require('body-parser');
const rateLimit = require('express-rate-limit');
const bruteforce = require('express-brute-mongoose');
const mongoose = require('mongoose');

// Set up Mongoose
mongoose.connect(process.env.MONGODB_URI);

// Set up the rate limiter
const rateLimiter = new rateLimit({
  windowMs: 60 * 1000, // 1 minute window
  max: 100, // limit each IP to 100 requests per windowMs
});

// Set up the brute force protection
const bruteforceProtection = new bruteforce({
  store: mongoose.connection,
  usernameField: 'username',
});

// Define your API routes
app.get('/users', async (req, res) => {
  // Retrieve a list of users
  const users = await User.find();
  res.json(users);
});

app.post('/users', async (req, res) => {
  // Create a new user
  const user = new User({ name: req.body.name });
  await user.save();
  res.status(201).json(user);
});

app.get('/users/:id', async (req, res) => {
  // Retrieve a specific user
  const user = await User.findById(req.params.id);
  if (!user) {
    res.status(404).json({ message: 'User not found' });
  } else {
    res.json(user);
  }
});

app.put('/users/:id', async (req, res) => {
  // Update a specific user
  const user = await User.findByIdAndUpdate(req.params.id, req.body, { new: true });
  if (!user) {
    res.status(404).json({ message: 'User not found' });
  } else {
    res.json(user);
  }
});

app.delete('/users/:id', async (req, res) => {
  // Delete a specific user
  const user = await User.findByIdAndRemove(req.params.id);
  if (!user) {
    res.status(404).json({ message: 'User not found' });
  } else {
    res.sendStatus(204);
  }
});
```
3. Set up the authentication system:
```javascript
// Define a function to check if a user is authenticated
const isAuthenticated = (req, res, next) => {
  // Check if there's an auth token in the request headers
  const authToken = req.headers['authorization'];
  if (!authToken) {
    return res.status(401).json({ message: 'Unauthorized' });
  }

  // Try to verify the auth token with the database
  User.findOne({ authToken }).then((user) => {
    if (!user) {
      return res.status(401).json({ message: 'Unauthorized' });
    } else {
      req.user = user;
      next();
    }
  });
};

// Use the isAuthenticated function as middleware for all routes that require authentication
app.use(isAuthenticated);
```
4. Set up rate limiting:
```javascript
// Use the rateLimiter middleware to limit requests per minute
app.use(rateLimiter);
```
5. Set up brute force protection:
```javascript
// Use the bruteforceProtection middleware to protect against brute force attacks
app.use(bruteforceProtection);
```
6. Start the server:
```bash
node api.js
```
This API will have the following features:

