```swift
struct TodoItem {
    let title: String
    let description: String
    let dueDate: Date
}

class TodoItemParser {
    enum Error: Swift.Error {
        case invalidData
    }

    func parse(fromData data: [String: Any]) throws -> TodoItem {
        guard let title = data["title"] as? String,
              let description = data["description"] as? String,
              let dueDate = data["dueDate"] as? Date else {
            throw Error.invalidData
        }

        return TodoItem(title: title, description: description, dueDate: dueDate)
    }
}
```
To handle the `TodoItemParser.Error.InvalidData` error, you can use a `do-catch` block to catch and print a failure message. Here's an example of how to do this:
