class QUBOProblem:
    def __init__(self, quadratic_coefficients):
        self.quadratic_coefficients = quadratic_coefficients

    def to_quso(self):
        quso_problem = {}
        for variable, coefficient in self.quadratic_coefficients.items():
            for other_variable, other_coefficient in self.quadratic_coefficients.items():
                if variable != other_variable:
                    quso_problem[variable] = quso_problem.get(variable, {})
                    quso_problem[variable][other_variable] = coefficient * other_coefficient
        return quso_problem

