```
def convert_to_quso(terms):
    quso = {}
    for term in terms:
        if len(term) == 1:
            # Handle self-loops (i.e., same variable quadratic terms)
            if term[0][0] not in quso:
                quso[term[0][0]] = {term[0]: [term]}
            else:
                quso[term[0][0]].append(term)
        else:
            # Optimize by avoiding redundant entries in the QUSO dictionary
            if term not in quso.values():
                quso[term[0][0]] = {term}
