[PYTHON]
def find_pairs(arr, target):
    # Create a hash table to store the counts of each number
    count_hash = {}
    for num in arr:
        if num not in count_hash:
            count_hash[num] = 1
        else:
            count_hash[num] += 1

    # Create a second hash table to store the pairs found
    pair_hash = {}

    # Iterate through the array and check if the complement of each number is in the hash table
    for i in range(len(arr)):
        complement = target - arr[i]
        if complement in count_hash:
            if count_hash[complement] > 0:
                # If the complement is in the hash table and there are remaining counts, add the pair to the pair hash
                pair_hash[(arr[i], complement)] = 1
            count_hash[complement] -= 1

    return len(pair_hash)
