Here is an example of how to parse a JSON response into a Python dictionary while ensuring that the "name" value is a string and the "age" value is an integer, and checking for additional requirements such as the length of the "name" value being at least 3 characters long and containing only alphabetic characters, the "age" value being between 18 and 99 (inclusive) and being a positive integer, and the presence of a "address" key in nested objects and its value being a string and not empty, and the presence of a "hobbies" key in nested arrays and its value being a list and containing at least one string element:
```
import json

def parse_json(data):
    # Create an empty dictionary to store the parsed data
    parsed_data = {}

    # Loop through each top-level key in the JSON response
    for key, value in data.items():
        # Check if the current key is a string and not empty
        if type(key) == str and len(key) > 0:
            # Add the key to the parsed dictionary with its corresponding value
            parsed_data[key] = value

            # Check if the current key is "name" and its value is a string
            if key == "name":
                # Ensure that the "name" value is at least 3 characters long and contains only alphabetic characters
                if len(value) < 3 or not value.isalpha():
                    raise ValueError("Invalid name")

            # Check if the current key is "age" and its value is an integer
            elif key == "age":
                # Ensure that the "age" value is between 18 and 99 (inclusive) and is a positive integer
                if not isinstance(value, int) or value < 18 or value > 99:
                    raise ValueError("Invalid age")

            # Check if the current key is "address" in a nested object
            elif key == "address":
                # Ensure that the "address" value is a string and not empty
                if type(value) != str or len(value) == 0:
                    raise ValueError("Invalid address")

            # Check if the current key is "hobbies" in a nested array
            elif key == "hobbies":
                # Ensure that the "hobbies" value is a list and contains at least one string element
                if not isinstance(value, list) or len(value) < 1:
                    raise ValueError("Invalid hobbies")

        # If the current key is a nested object, recursively parse its contents
        elif type(value) == dict:
            parsed_data[key] = parse_json(value)

        # If the current key is a nested array, recursively parse its contents
        elif type(value) == list:
            parsed_data[key] = [parse_json(item) for item in value]

    return parsed_data
```
This function takes a JSON response as input and returns a Python dictionary with the parsed data. It uses recursion to parse the nested objects and arrays, and checks for additional requirements such as the length of the "name" value being at least 3 characters long and containing only alphabetic characters, the "age" value being between 18 and 99 (inclusive) and being a positive integer, and the presence of a "address" key in nested objects and its value being a string and not empty, and the presence of a "hobbies" key in nested arrays and its value being a list and containing at least one string element.

