class StudentRecords {
    private Map<String, Integer> ages;
    private Map<String, Double> scores;
    private Map<String, Boolean> attendance;

    public StudentRecords() {
        this.ages = new HashMap<>();
        this.scores = new HashMap<>();
        this.attendance = new HashMap<>();
    }

    // Method to add a new student with their full name and age
    public void addStudent(String name, int age) {
        if (age < 0) {
            throw new IllegalArgumentException("Age cannot be negative");
        }
        this.ages.put(name, age);
    }

    // Method to modify a student's age
    public void updateAge(String name, int age) {
        if (age < 0) {
            throw new IllegalArgumentException("Age cannot be negative");
        }
        this.ages.put(name, age);
    }

    // Method to add a new student with their full name and score on an academic assignment
    public void addScore(String name, double score) {
        if (score < 0) {
            throw new IllegalArgumentException("Score cannot be negative");
        }
        this.scores.put(name, score);
    }

    // Method to modify a student's score on an academic assignment
    public void updateScore(String name, double score) {
        if (score < 0) {
            throw new IllegalArgumentException("Score cannot be negative");
        }
        this.scores.put(name, score);
    }

    // Method to add a new student with their full name and attendance status for a given day
    public void addAttendance(String name, boolean attended) {
        this.attendance.put(name, attended);
    }

    // Method to modify a student's attendance status for a given day
    public void updateAttendance(String name, boolean attended) {
        this.attendance.put(name, attended);
    }

    // Method to calculate and return the average age of all students
    public double getAverageAge() {
        int totalAge = 0;
        for (Integer age : ages.values()) {
            totalAge += age;
        }
        return totalAge / ages.size();
    }

    // Method to find and return the top performer based on score
    public String getTopPerformer() {
        double highestScore = -1;
        String topPerformer = "";
        for (String name : scores.keySet()) {
            if (scores.get(name) > highestScore) {
                highestScore = scores.get(name);
                topPerformer = name;
            }
        }
        return topPerformer;
    }

    // Method to find and return the most frequently absent student
    public String getMostAbsentStudent() {
        int maxFrequency = 0;
        String mostAbsentStudent = "";
        for (String name : attendance.keySet()) {
            if (attendance.get(name) == false && attendance.get(name) > maxFrequency) {
                maxFrequency = attendance.get(name);
                mostAbsentStudent = name;
            }
        }
        return mostAbsentStudent;
    }

    // Method to generate a report card for a specific pupil with attendance and performance metrics
    public String getReportCard(String name) {
        if (!ages.containsKey(name)) {
            throw new IllegalArgumentException("Name not found");
        }
        if (!scores.containsKey(name)) {
            throw new IllegalArgumentException("Name not found");
        }
        if (!attendance.containsKey(name)) {
            throw new IllegalArgumentException("Name not found");
        }
        return "Student Name: " + name + "\n" +
                "Age: " + ages.get(name) + "\n" +
                "Academic Performance Score: " + scores.get(name) + "\n" +
                "Attendance Status: " + attendance.get(name);
    }
}

