```python
def count_unique_elements(input_list):
    # Initialize an empty dictionary to store the counts
    element_counts = {}

    # Iterate through the input list
    for element in input_list:
        # Check if the current element is a string, integer, or list
        if not isinstance(element, (str, int, list)):
            # If it's not, raise a custom exception
            raise InvalidInputError("Invalid input type")

        # If the current element is a string or integer, add it to the dictionary
        elif isinstance(element, str) or isinstance(element, int):
            if element in element_counts:
                element_counts[element] += 1
            else:
                element_counts[element] = 1

        # If the current element is a list, count its unique elements recursively
        elif isinstance(element, list):
            # Recursively call the function to count the unique elements in the sublist
            sublist_counts = count_unique_elements(element)

            # Add the counts of the sublist to the dictionary
            for key, value in sublist_counts.items():
                if key in element_counts:
                    element_counts[key] += value
                else:
                    element_counts[key] = value

    return element_counts
```
