function characterFrequency(arr) {
  let counts = {}; // object to store character frequencies

  // iterate over the array and count the frequency of each character
  arr.forEach((element) => {
    if (typeof element === 'string') {
      for (let char of element) {
        if (!counts[char]) {
          counts[char] = 0;
        }
        counts[char]++;
      }
    } else if (Array.isArray(element)) {
      // handle nested arrays within the main array
      characterFrequency(element);
    }
  });

  // sort the output by frequency and alphabetical order
  let sortedCounts = Object.entries(counts).sort((a, b) => {
