Here is an example implementation of the `calculateFinalPrice` function in JavaScript:
```javascript
function calculateFinalPrice(originalPrice, serviceCenter, serviceType) {
  const discountRates = {
    serviceCenters: {
      center1: {
        discountRate: 0.1
      },
      center2: {
        discountRate: 0.15
      }
    },
    serviceTypes: {
      type1: {
        discountRate: 0.05
      },
      type2: {
        discountRate: 0.1
      }
    }
  };

  let finalPrice = originalPrice;

  // Check if the service center and service type are in the discount rates object
  if (discountRates.serviceCenters[serviceCenter] && discountRates.serviceTypes[serviceType]) {
    const serviceCenterDiscountRate = discountRates.serviceCenters[serviceCenter].discountRate;
    const serviceTypeDiscountRate = discountRates.serviceTypes[serviceType].discountRate;

    // Calculate the final price after applying the discounts
    finalPrice = originalPrice - (originalPrice * serviceCenterDiscountRate) - (originalPrice * serviceTypeDiscountRate);
  }

  return finalPrice;
}
```
