[PYTHON]
def is_armstrong_prime(n):
    # Check if the number is an Armstrong number
    armstrong = True
    temp = n
    sum = 0
    while temp > 0:
        digit = temp % 10
        sum += digit ** 3
        temp //= 10
    if sum == n:
        # Check if the number is a prime number
        prime = True
        for i in range(2, int(n ** 0.5) + 1):
            if n % i == 0:
                prime = False
                break
        if prime:
            print(f"{n} is an Armstrong prime number.")
    else:
        armstrong = False
    return armstrong

def get_armstrong_primes(start, end):
    for num in range(start, end + 1):
        if is_armstrong_prime(num):
            print(f"{num} is an Armstrong number.")

if __name__ == "__main__":
    get_armstrong_primes(100, 1000)
