def print_spiral_matrix(n):
    matrix = []
    for i in range(n):
        matrix.append(['B'] * n)

    count = 1
    direction = 'right'

    for layer in range(n // 2):
        # Traverse from left to right
        if direction == 'right':
            for i in range(layer, n - layer - 1):
                matrix[layer][i] = count
                count += 1

        # Traverse from right to left
        elif direction == 'left':
            for i in range(layer, n - layer - 1):
                matrix[layer][n - i - 1] = count
                count += 1

        # Traverse from bottom to top
        elif direction == 'up':
            for i in range(layer, n - layer - 1):
                matrix[n - i - 1][n - layer - 1] = count
                count += 1

        # Traverse from top to bottom
        elif direction == 'down':
            for i in range(layer, n - layer - 1):
                matrix[n - layer - 1][i] = count
                count += 1

        # Update direction
        if layer == n // 2:
            direction = 'right'
        elif direction == 'right':
            direction = 'down'
        elif direction == 'down':
            direction = 'left'
        else:
            direction = 'up'

    return matrix
[/PYTHON]
