Method 1: Brute Force Method
-----------------------------

```
def get_perfect_numbers(a, b):
    perfect_numbers = []
    for i in range(a, b+1):
        sum_of_divisors = 0
        for j in range(1, i+1):
            if i % j == 0:
                sum_of_divisors += j
        if sum_of_divisors == i:
            perfect_numbers.append(i)
    return perfect_numbers
```

Method 2: Multithreaded Method
------------------------------

```
import threading

def get_perfect_numbers(a, b):
    num_threads = 4
    chunk_size = (b-a+1) // num_threads
    perfect_numbers = []

    def calculate_perfect_numbers(start, end):
        for i in range(start, end+1):
            sum_of_divisors = 0
            for j in range(1, i+1):
                if i % j == 0:
                    sum_of_divisors += j
            if sum_of_divisors == i:
                perfect_numbers.append(i)

    threads = [threading.Thread(target=calculate_perfect_numbers, args=(a+chunk_size*i, a+chunk_size*(i+1))) for i in range(num_threads)]
    for thread in threads:
        thread.start()
    for thread in threads:
        thread.join()

    return perfect_numbers
```

