class Volume:
    """
    Compute the volume of various 3D geometric shapes.

    Attributes:
        shape (str): The name of the shape.
        dimensions (list[float]): The dimensions of the shape.

    Methods:
        compute_volume(self) -> float: Compute the volume of the shape.
        validate_inputs(self, shape: str, dimensions: list[float]) -> bool: Validate if the inputs correspond to an actual physical shape.
    """

    def __init__(self, shape: str, dimensions: list[float]):
        self.shape = shape
        self.dimensions = dimensions

    def compute_volume(self) -> float:
        """Compute the volume of the shape."""
        if not self.validate_inputs():
            raise ValueError("Invalid inputs.")

        if self.shape == "cube":
            return self.dimensions[0] ** 3
        elif self.shape == "cylinder":
            return pi * self.dimensions[1] ** 2 * self.dimensions[2]
        elif self.shape == "sphere":
            return (4 / 3) * pi * self.dimensions[0] ** 3
        elif self.shape == "cone":
            return (1 / 3) * pi * self.dimensions[1] ** 2 * self.dimensions[2]
        elif self.shape == "frustum":
            return (1 / 3) * pi * self.dimensions[0] ** 2 * self.dimensions[1] * self.dimensions[3]
        elif self.shape == "torus":
            return pi * (self.dimensions[0] ** 2 + self.dimensions[1] ** 2)
        else:
            raise ValueError("Invalid shape.")

    def validate_inputs(self, shape: str, dimensions: list[float]) -> bool:
        """Validate if the inputs correspond to an actual physical shape."""
        # Check if the shape is valid.
        if shape not in ["cube", "cylinder", "sphere", "cone", "frustum", "torus"]:
            return False

        # Check if the dimensions are valid for each shape.
        if shape == "cube":
            if len(dimensions) != 1:
                return False
        elif shape == "cylinder" or shape == "cone" or shape == "frustum":
            if len(dimensions) != 3:
                return False
        elif shape == "sphere":
            if len(dimensions) != 1:
                return False
        elif shape == "torus":
            if len(dimensions) != 2:
                return False

        # Check if the dimensions are positive.
        for dimension in dimensions:
            if dimension <= 0:
                return False

        return True

