import random

def is_prime(n: int) -> bool:
    """Check if n is a prime number."""
    if n <= 1:
        return False
    if n == 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    for i in range(5, int(n ** 0.5) + 1, 6):
        if n % i == 0 or n % (i + 2) == 0:
            return False
    return True

def next_composite(n: int) -> int:
    """Return the next composite number after n."""
    while True:
        n += 1
        if not is_prime(n):
            return n

def prime_duplicate_special_shuffle(s: str) -> str:
    """Transform the input string according to the problem's constraints."""
    transformed = ""
    for c in s:
        if c.isalnum():
            # Neuter case
            transformed += c.lower() if c.islower() else c.upper()
        elif c.isdigit() and int(c) % 2 == 1 and is_prime(int(c)):
            # Replace digit with next composite number
            transformed += str(next_composite(int(c)))
        else:
            transformed += c
    return transformed
