Here is a possible implementation of the game:
```
#include <iostream>
#include <cstdlib>
#include <ctime>
using namespace std;

int main() {
    // Prompt the user to input their choice
    cout << "Enter your choice (rock, paper, or scissors): ";
    string userChoice;
    cin >> userChoice;

    // Convert the user's choice to lowercase for case-insensitivity
    transform(userChoice.begin(), userChoice.end(), userChoice.begin(), ::tolower);

    // Check if the input is valid
    if (userChoice != "rock" && userChoice != "paper" && userChoice != "scissors") {
        cout << "Invalid choice. Try again." << endl;
        return 0;
    }

    // Generate a random choice for the computer
    srand(time(0));
    int computerChoice = rand() % 3 + 1;

    // Determine the winner based on the rules
    string outcome;
    if (userChoice == "rock" && computerChoice == 2) {
        outcome = "Win";
    } else if (userChoice == "scissors" && computerChoice == 1) {
        outcome = "Win";
    } else if (userChoice == "paper" && computerChoice == 3) {
        outcome = "Win";
    } else if (userChoice == computerChoice) {
        outcome = "Tie";
    } else {
        outcome = "Lose";
    }

    // Display the results
    cout << "Your choice: " << userChoice << endl;
    cout << "Computer's choice: ";
    switch (computerChoice) {
        case 1: cout << "rock"; break;
        case 2: cout << "scissors"; break;
        case 3: cout << "paper"; break;
    }
    cout << endl << "Outcome: " << outcome << endl;

    // Wait for the user to press a key before exiting
    cin.ignore(numeric_limits<streamsize>::max(), '\n');
    return 0;
}
```
This program uses the `transform()` function from `<algorithm>` to convert the user's input to lowercase, and the `rand()` function from `<cstdlib>` to generate a random number between 1 and 3 for the computer's choice. The program then compares the two choices based on the rules of rock-paper-scissors and determines the outcome. Finally, it displays the results to the user and waits for input before exiting.

