    Optimize the process of finding prime factors.
    >>> largest_prime_factor(13195)
    29
    >>> largest_prime_factor(2048)
    2
    >>> largest_prime_factor(-13195)
    29
    """
    if n < 0:
        return largest_prime_factor(-n)
    if n == 1 or is_prime(n):
        return n
