public class ClosureExample {
  public static void main(String[] args) {
    // Create a closure that takes in a string and a number
    // and returns a new function that concatenates the string
    // with a given number of exclamation marks
    Closure<String> closure = (str, num) -> {
      return () -> str + "!" + num;
    };

    // Create an array of closures
    Closure<String>[] closures = new Closure[]{
      closure.apply("Hello", 3),
      closure.apply("World", 5)
    };

    // Invoke each closure with the same string
    String result = "";
    for (Closure<String> c : closures) {
      result += c.apply("Java");
    }

    System.out.println(result);
  }
}
