import Control.Monad (replicateM)

createClosure :: String -> Int -> IO (String -> String)
createClosure str num = return $ \str' -> str' ++ concat (replicate num "!")

invokeClosures :: [IO (String -> String)] -> String -> IO String
invokeClosures closures str = foldlM (\res closure -> do { res' <- res; closure' <- closure; return $ res' ++ closure' str }) (return "") closures

main :: IO ()
