class Employee:
    def __init__(self, name: str, experience: int, salary: int):
        self.name = name
        self.experience = experience
        self.salary = salary
        self.projects = {}

    def add_project(self, project_name: str, duration: int, role: str):
        if project_name in self.projects:
            self.projects[project_name]["duration"] += duration
            self.projects[project_name]["role"] = role
        else:
            self.projects[project_name] = {"duration": duration, "role": role}

    def get_total_experience(self) -> int:
        total_experience = 0
        for project in self.projects.values():
            total_experience += project["duration"]
        return total_experience

    def get_average_salary(self) -> float:
        if len(self.projects) == 0:
            return 0.0
        else:
            return self.salary / len(self.projects)

    def get_project_names(self) -> List[str]:
        return list(self.projects.keys())

    def get_project_duration(self, project_name: str) -> int:
        if project_name in self.projects:
            return self.projects[project_name]["duration"]
        else:
            raise KeyError("Project not found")

    def get_project_role(self, project_name: str) -> str:
        if project_name in self.projects:
            return self.projects[project_name]["role"]
        else:
            raise KeyError("Project not found")
