fn prime_factors(n: i32) -> Vec<i32> {
    let mut factors = vec![];

    if n == 0 || n == 1 {
        return factors;
    }

    for i in 2..n {
        if n % i == 0 {
            factors.push(i);
            factors.append(&mut prime_factors(n / i));
            break;
        }
    }

    factors
}
