Here is an example of how this could be implemented in Python:
```
def is_prime(n):
    if n <= 1 or n % 2 == 0:
        return False
    for i in range(3, int(n ** 0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def is_palindrome(n):
    return str(n) == str(n)[::-1]

def reverse(n):
    return int(str(n)[::-1])

def is_emirp(n):
    if not is_prime(n) or is_palindrome(n):
        return False
    if not is_prime(reverse(n)):
        return False
    return True

def emirp_root(n):
    if not is_emirp(n):
        raise ValueError("The number is not an emirp.")
    return min([i for i in range(1, int(n ** 0.5) + 1) if n % i == 0 and is_prime(i)])

def main():
    num = input("Enter a number: ")
    try:
        num = int(num)
    except ValueError:
        print("Invalid input.")
        return
    if not (1 <= num <= 10000):
        print("Number out of range.")
        return
    if is_emirp(num):
        root = emirp_root(num)
        print(f"The number {num} is an emirp with emirp root {root}.")
    else:
        if not is_prime(num):
            print("The number is not prime.")
        elif is_palindrome(num):
            print("The number is a palindrome.")
        else:
            print("The reverse of the number is not prime.")
```
