```java
import java.util.HashMap;
import java.util.Map;

public class Bank {
    private Map<Integer, BankAccount> accounts = new HashMap<>();

    public void createAccount(int accountNumber, double initialBalance, String pin) {
        if (accounts.containsKey(accountNumber)) {
            throw new IllegalArgumentException("Account number is already in use");
        }
        BankAccount account = new BankAccount(accountNumber, initialBalance, pin);
        accounts.put(accountNumber, account);
    }

    public BankAccount getAccount(int accountNumber) {
        return accounts.get(accountNumber);
    }
}

class BankAccount {
    private int accountNumber;
    private double balance;
    private String pin;

    public BankAccount(int accountNumber, double initialBalance, String pin) {
        this.accountNumber = accountNumber;
        this.balance = initialBalance;
        this.pin = pin;
    }

    public void deposit(double amount) {
        balance += amount;
    }

    public void withdraw(double amount) {
        if (amount > balance) {
            throw new IllegalArgumentException("Insufficient funds");
        }
        balance -= amount;
    }

    public double checkBalance() {
        return balance;
    }

    public boolean validatePin(String enteredPin) {
        return enteredPin.equals(pin);
    }
}
```
