function getMedian(arr) {
  // Step 1: Initialize the array with the given numbers
  const nums = [x, y, z, w, a, b];

  // Step 2: Sort the array in ascending order using a custom sorting algorithm
  nums.sort((a, b) => {
    return a - b;
  });

  // Step 3: Check if the length of the array is even or odd
  const isEven = (nums.length % 2 === 0);

  // Step 4: If the length is even, the median is the average of the middle two elements
  if (isEven) {
    const mid1 = nums[Math.floor(nums.length / 2)];
    const mid2 = nums[Math.ceil(nums.length / 2)];
    return (mid1 + mid2) / 2;
  }

  // Step 5: If the length is odd, the median is the middle element
  const mid = nums[Math.floor((nums.length - 1) / 2)];
  return mid;
}

