function sortArray(arr) {
    let sortedArr = [];

    // loop through the array and push each element into a new array in order
    for (let i = 0; i < arr.length; i++) {
        let currentElement = arr[i];
        let insertIndex = findInsertIndex(sortedArr, currentElement);
        sortedArr.splice(insertIndex, 0, currentElement);
