}

function findInsertIndex(arr, element) {
    // loop through the array and find the first index where the element should be inserted
    for (let i = 0; i < arr.length; i++) {
        if (element < arr[i]) {
            return i;
        }
    }

    // if the element is greater than all other elements in the array, insert it at the end
    return arr.length;
}

