def k_means(data_points, k):
    # Initialize K cluster centroids randomly from the data points
    cluster_centroids = []
    for i in range(k):
        random_index = random.randint(0, len(data_points) - 1)
        cluster_centroids.append(data_points[random_index])

    # Assign each data point to the nearest cluster centroid
    cluster_assignments = {}
    for i in range(len(data_points)):
        min_distance = float("inf")
        closest_cluster = -1
        for j in range(k):
            distance = dist(data_points[i], cluster_centroids[j])
            if distance < min_distance:
                min_distance = distance
                closest_cluster = j
        cluster_assignments[i] = closest_cluster

    # Recalculate the cluster centroids based on the assigned data points
    for i in range(k):
        points = [data_points[j] for j in range(len(data_points)) if cluster_assignments[j] == i]
        if len(points) == 0:
            continue
        centroid = sum(points) / len(points)
        cluster_centroids[i] = centroid

    # Repeat steps 2 and 3 until the cluster assignments stabilize or a maximum number of iterations is reached
    num_iterations = 0
    prev_assignments = None
    while not stable(cluster_assignments, prev_assignments) and num_iterations < MAX_ITERATIONS:
        prev_assignments = copy.deepcopy(cluster_assignments)
        for i in range(len(data_points)):
            min_distance = float("inf")
            closest_cluster = -1
            for j in range(k):
                distance = dist(data_points[i], cluster_centroids[j])
                if distance < min_distance:
                    min_distance = distance
                    closest_cluster = j
            cluster_assignments[i] = closest_cluster
        for i in range(k):
            points = [data_points[j] for j in range(len(data_points)) if cluster_assignments[j] == i]
            if len(points) == 0:
                continue
            centroid = sum(points) / len(points)
            cluster_centroids[i] = centroid
        num_iterations += 1

    # Return the final cluster assignments and the cluster centroids
    return (cluster_assignments, cluster_centroids)

def stable(cluster_assignments, prev_assignments):
    if prev_assignments is None:
        return False
    for i in range(len(data_points)):
        if cluster_assignments[i] != prev_assignments[i]:
            return False
    return True

def dist(p1, p2):
    return ((p1[0] - p2[0]) ** 2 + (p1[1] - p2[1]) ** 2) ** 0.5

