A Binary Search Tree (BST) is a data structure that allows for efficient search, insertion, and deletion of nodes. It works by recursively partitioning the set of keys into smaller subsets based on their relative order, with each subtree representing a subset of keys. The self-balancing property ensures that the height of the tree remains relatively constant, allowing for efficient search operations in O(log n) time complexity.

Here's an example implementation of a BST in Java:
```
public class BinarySearchTree {
  private Node root;

  // Node is a data structure representing a node in the tree
  private static class Node {
    int key;
    Node left, right;

    public Node(int key) {
      this.key = key;
    }
  }

  // Insert inserts a new node with the given key into the tree
  public void insert(int key) {
    root = insert(root, key);
  }

  // Recursive method for inserting a new node
  private Node insert(Node node, int key) {
    if (node == null) {
      return new Node(key);
    }

    int cmp = compareKeys(key, node.key);
    if (cmp < 0) {
      node.left = insert(node.left, key);
    } else if (cmp > 0) {
      node.right = insert(node.right, key);
    }

    return balance(node);
  }

  // Delete deletes a node with the given key from the tree
  public void delete(int key) {
    root = delete(root, key);
  }

  // Recursive method for deleting a node
  private Node delete(Node node, int key) {
    if (node == null) {
      return null;
    }

    int cmp = compareKeys(key, node.key);
    if (cmp < 0) {
      node.left = delete(node.left, key);
    } else if (cmp > 0) {
      node.right = delete(node.right, key);
    } else {
      // If the node has no children, simply remove it
      if (node.left == null && node.right == null) {
        return null;
      }

      // If the node has only one child, replace it with that child
      Node child = (node.left != null) ? node.left : node.right;
      node = child;
    }

    return balance(node);
  }

  // Search searches for a node with the given key in the tree
  public Node search(int key) {
    return search(root, key);
  }

  // Recursive method for searching for a node
  private Node search(Node node, int key) {
    if (node == null) {
      return null;
    }

    int cmp = compareKeys(key, node.key);
    if (cmp < 0) {
      return search(node.left, key);
    } else if (cmp > 0) {
      return search(node.right, key);
    }

    return node;
  }

  // Balance balances the tree by rotating nodes as needed to maintain a balance of log(n) height
  private Node balance(Node node) {
    if (node == null) {
      return null;
    }

    int diff = balanceFactor(node);
    if (diff > 1) {
      // If the tree is too left-heavy, rotate to the right
      if (balanceFactor(node.left) < 0) {
        node.left = rotateRight(node.left);
      }
      return rotateLeft(node);
    } else if (diff < -1) {
      // If the tree is too right-heavy, rotate to the left
      if (balanceFactor(node.right) > 0) {
        node.right = rotateLeft(node.right);
      }
      return rotateRight(node);
    }

    return node;
  }

  // CompareKeys compares two keys and returns a negative integer if the first key is less than the second, a positive integer if the first key is greater than the second, or zero if they are equal.
  private int compareKeys(int key1, int key2) {
    return (key1 < key2) ? -1 : ((key1 == key2) ? 0 : 1);
  }

  // BalanceFactor returns the balance factor of a node, which is its height minus the height of its two children plus one.
  private int balanceFactor(Node node) {
    if (node == null) {
      return 0;
    }

    return Math.max(height(node.left), height(node.right)) - Math.min(height(node.left), height(node.right)) + 1;
  }

  // Height returns the height of a node, which is the maximum depth of its left and right subtrees plus one.
  private int height(Node node) {
    if (node == null) {
      return 0;
    }

    return Math.max(height(node.left), height(node.right)) + 1;
  }

  // RotateLeft rotates a left subtree of a node to the right.
  private Node rotateLeft(Node node) {
    if (node == null) {
      return null;
    }

    Node right = node.right;
    node.right = right.left;
    right.left = node;
    return right;
  }

  // RotateRight rotates a right subtree of a node to the left.
  private Node rotateRight(Node node) {
    if (node == null) {
      return null;
    }

    Node left = node.left;
    node.left = left.right;
    left.right = node;
    return left;
  }
}
```
This implementation ensures that the tree remains self-balancing by using a balance factor to determine when rotations are needed, and by implementing rotation methods for both left and right rotations. It also supports insertion, deletion, and search operations in O(log n) time complexity by recursively partitioning the set of keys into smaller subsets based on their relative order, with each subtree representing a subset of keys.

