CREATE PROCEDURE FindStudentsEnrolledInCourse(IN p_courseName VARCHAR(50))
BEGIN
    -- Declare variables to store the results of the query
    DECLARE v_studentId INT;
    DECLARE v_studentName VARCHAR(100);
    DECLARE v_courseName VARCHAR(50);
    DECLARE v_dateEnrolled DATE;
    DECLARE v_numberOfCourses INT;
    DECLARE v_averageGPA FLOAT;

    -- Query to find students enrolled in the specified course
    SELECT 
        s.Id AS StudentId,
        s.Name AS StudentName,
        c.Name AS CourseName,
        s.DateEnrolled AS DateEnrolled,
        COUNT(DISTINCT c.Id) AS NumberOfCourses,
        AVG(c.GPA) AS AverageGPA
    FROM 
        students s
    INNER JOIN 
        courses c ON s.CourseId = c.Id
    WHERE 
        c.Name = p_courseName
    GROUP BY 
        s.Id, s.Name, c.Name, s.DateEnrolled
    ORDER BY 
        2 DESC;

    -- Return the results of the query as a result set
    RETURN v_studentId, v_studentName, v_courseName, v_dateEnrolled, v_numberOfCourses, v_averageGPA;
END;

