def get_odd_occurring_elements(my_array):
    result = {}
    for i in range(len(my_array)):
        counts = {}
        for num in my_array[i]:
            if num in counts:
                counts[num] += 1
            else:
                counts[num] = 1
        odd_counts = [v for v in counts.values() if v % 2 == 1]
        if len(odd_counts) > 0:
            result[i] = odd_counts[0]
        else:
            result[i] = -1
    return result
