```
#include <iostream>
#include <string>

// Function to convert a binary string to a hexadecimal string
std::string binToHex(const std::string& binary) {
  // Check if the input is a valid binary string
  if (!isBinaryString(binary)) {
    throw std::invalid_argument("Input must be a valid binary string");
  }

  // Convert the binary string to a hexadecimal string
  std::string hex = "";
  for (int i = 0; i < binary.size(); i++) {
    char c = binary[i];
    if (c == '1') {
      hex += "F";
    } else if (c == '0') {
      hex += "0";
    } else {
      throw std::invalid_argument("Input must be a valid binary string");
    }
  }
  return hex;
}

// Function to check if a string is a valid binary string
bool isBinaryString(const std::string& str) {
  for (int i = 0; i < str.size(); i++) {
    char c = str[i];
    if (c != '1' && c != '0') {
      return false;
    }
  }
  return true;
}

int main() {
  std::string binary = "1010";
  std::cout << binToHex(binary) << std::endl; // Output: A
  return 0;
}
```
