import lxml.etree as etree

class XMLValidator:
    def validate(self, schema_path, target_path):
        # Parse the XML schema from the schema_path using etree.parse
        schema_root = etree.parse(schema_path).getroot()

        # Create an XML schema object using etree.XMLSchema
        xml_schema = etree.XMLSchema(schema_root)

        # Parse the XML from the target_path using etree.parse
        try:
            xml_root = etree.parse(target_path).getroot()
        except etree.XMLSyntaxError as err:
            return ValidationResult(passed=False, error_log=str(err))

        # Validate the parsed XML against the XML schema using the validate method of the XML schema object
        try:
            xml_schema.validate(xml_root)
        except etree.XMLSchemaError as err:
            return ValidationResult(passed=False, error_log=str(err))

        # If validation is successful, return a ValidationResult object with passed set to True and error_log set to the XML schema's error log
        return ValidationResult(passed=True, error_log=xml_schema.error_log)
