def get_sum(n):
    if n == 0:
        return 0
    else:
        # Use memoization to store the results of previous calculations
        memo = {}
        def helper(n):
            if n in memo:
                return memo[n]
            else:
                memo[n] = get_sum(n-1) + 1
                return memo[n]
        return helper(n)

# Collect user input
while True:
    try:
        n = int(input("Enter a positive integer: "))
        if n > 0:
            break
        else:
            print("Invalid input. Please enter a positive integer.")
    except ValueError:
        print("Invalid input. Please enter a positive integer.")

# Call the function with the user's input
print(get_sum(n))
```
