def get_permutations(numbers):
    permutations = []
    if len(numbers) == 0:
        return permutations
    elif len(numbers) == 1:
        return [numbers]
    else:
        for i in range(len(numbers)):
            for perm in get_permutations(numbers[:i] + numbers[i+1:]):
                permutations.append([numbers[i]] + perm)
        return permutations

def all_meet_condition(permutations, condition):
    for perm in permutations:
        if not condition(perm):
            return False
    return True

def is_prime(n):
    if n == 1:
        return False
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True

def main():
    numbers = [1, 2, 3]
    permutations = get_permutations(numbers)
    print(permutations)
    print(all_meet_condition(permutations, lambda x: is_prime(sum(x))))

if __name__ == "__main__":
    main()
