```
-- Load data from a CSV file into a Hive table
CREATE TABLE my_data (id INT, name STRING) ROW FORMAT DELIMITED FIELDS TERMINATED BY ',';
LOAD DATA INPATH 'my_data.csv' INTO TABLE my_data;

-- Filter the data based on a condition
SELECT * FROM my_data WHERE id > 10;

-- Group by and aggregate the data
SELECT AVG(id), COUNT(*) FROM my_data GROUP BY name;

-- Join two tables together
CREATE TABLE my_data2 (id INT, name STRING) ROW FORMAT DELIMITED FIELDS TERMINATED BY ',';
LOAD DATA INPATH 'my_data2.csv' INTO TABLE my_data2;
SELECT * FROM my_data JOIN my_data2 ON my_data.name = my_data2.name;

-- Sort the data
SELECT * FROM my_data ORDER BY id DESC;
```
