public class PascalTriangle {

public static void main(String[] args) {
int n = 5; // Input: the number of rows in the Pascal Triangle
printPascalTriangle(n);
}

private static void printPascalTriangle(int n) {
// Initialize the first row with 1s
int[] row = new int[n + 1];
for (int i = 0; i <= n; i++) {
row[i] = 1;
}

// Print the first row
System.out.println(Arrays.toString(row));

// Iterate through the remaining rows
for (int i = 1; i < n; i++) {
// Calculate the current row using the previous row
row[0] = 1;
for (int j = 1; j < i + 1; j++) {
row[j] = row[j - 1] + row[j];
}
row[i + 1] = 1;

// Print the current row
System.out.println(Arrays.toString(row));
}
}
}

