Here's the Java adaptation of the given code:
```
import java.util.*;

public class UltraFibonacci {
    public static void main(String[] args) {
        int n = Integer.parseInt(args[0]);
        int m = Integer.parseInt(args[1]);

        // Function to check if a number is prime or not
        boolean checkPrime(int num) {
            if (num > 1) {
                for (int i = 2; i <= num / 2; i++) {
                    if (num % i == 0) {
                        return false;
                    }
                }
                return true;
            } else {
                return false;
            }
        }

        // Function to check if a number is recurring or not
        boolean checkRecurring(int num) {
            String strNum = Integer.toString(num);
            Set<Character> chars = new HashSet<>();
            for (char c : strNum.toCharArray()) {
                if (chars.contains(c)) {
                    return false;
                } else {
                    chars.add(c);
                }
            }
            return true;
        }

        // Function to check if a number is a perfect square or not
        boolean checkPerfectSquare(int num) {
            double root = Math.sqrt(num);
            return (root % 1 == 0);
        }

        List<Integer> fib = new ArrayList<>();
        fib.add(0);
        fib.add(1);
        for (int i = 2; i <= n; i++) {
            int sum = fib.get(i - 1) + fib.get(i - 2);
            if (checkPrime(sum) && checkRecurring(sum) && !checkPerfectSquare(sum)) {
                fib.add(sum);
            }
        }

        System.out.println("The first " + n + " numbers that are multiple of " + m + " and have prime sum, recurring digits, but not perfect squares are:");
        for (int i = 0; i < fib.size(); i++) {
            if (fib.get(i) % m == 0) {
                System.out.println(fib.get(i));
            }
        }
    }
}
```
