class Converter {
    private Map<Integer, Float> conversionRates;

    public Converter() {
        // Load the conversion rates from a file or database
        conversionRates = new HashMap<>();
        conversionRates.put(1, 0.8f);
        conversionRates.put(2, 1.2f);
        conversionRates.put(3, 0.6f);
    }

    public float convert(int amount, int fromUnit, int toUnit) {
        float rate = conversionRates.get(fromUnit).floatValue();
        return (amount / rate) * conversionRates.get(toUnit).floatValue();
    }
}
```
