func filterJSONObject(_ jsonObj: [String: Any]) -> [String: Any] {
    var filteredDict = [String: Any]()

    for (key, value) in jsonObj {
        if let dictValue = value as? [String: Any], key == "age" {
            if let age = dictValue["age"] as? Int, age >= 35 {
                filteredDict[key] = value
            }
        } else {
            filteredDict[key] = value
        }
    }

    return filteredDict
}

func addIsExperienced(_ jsonObj: [String: Any]) -> [String: Any] {
    var updatedDict = [String: Any]()

    for (key, value) in jsonObj {
        if key == "age" {
            updatedDict["isExperienced"] = value >= 35
        } else {
            updatedDict[key] = value
        }
    }

    return updatedDict
}

func main() -> [String: Any] {
    let jsonData = """
    {"name": "John", "age": 30, "city": "New York", "yearsOfExperience": 5, "title": "Engineer"}
    """.data(using: .utf8)!

    do {
        let jsonObj = try JSONSerialization.jsonObject(with: jsonData) as! [String: Any]
        let filteredDict = filterJSONObject(jsonObj)
        let updatedDict = addIsExperienced(filteredDict)

        return updatedDict
    } catch {
        print("Error parsing JSON: \(error)")
    }

    return [String: Any]()
}

main()
