def stop_vna(vna_path):
    # Stop the network analyzer application
    try:
        subprocess.run(["pgrep", "-f", "vna"], stdout=subprocess.PIPE, stderr=subprocess.STDOUT)
    except subprocess.CalledProcessError as e:
        print("The network analyzer application is not running.")
        sys.exit(1)

    try:
        subprocess.run(["killall", "vna"], stdout=subprocess.PIPE, stderr=subprocess.STDOUT)
    except subprocess.CalledProcessError as e:
        print("Failed to stop the network analyzer application.")
        sys.exit(1)
    else:
        print("The network analyzer application has been stopped.")

def restart_vna(vna_path):
    # Stop and start the network analyzer application
    try:
        subprocess.run(["pgrep", "-f", "vna"], stdout=subprocess.PIPE, stderr=subprocess.STDOUT)
    except subprocess.CalledProcessError as e:
