public static int[] getUniqueElements(int[] array) {
    // Check if the array is null or empty
    if (array == null || array.length == 0) {
        return new int[0];
    }

    // Create a hash set to store unique elements
    Set<Integer> uniqueSet = new HashSet<>();

    // Iterate over the array and add each element to the set
    for (int i = 0; i < array.length; i++) {
        uniqueSet.add(array[i]);
    }

    // Create a new array to store the unique elements
    int[] uniqueArray = new int[uniqueSet.size()];

    // Add each unique element from the set to the array
    int index = 0;
    for (Integer element : uniqueSet) {
        uniqueArray[index++] = element;
    }

    return uniqueArray;
}
