def get_prime_numbers(my_list):
    prime_numbers = []
    for num in my_list:
        if is_prime(num):
            prime_numbers.append(num)
    twin_primes = []
    for i in range(len(prime_numbers)):
        if is_prime(prime_numbers[i] + 2) and is_prime(prime_numbers[i] - 2):
            twin_primes.append((prime_numbers[i], True))
        else:
            twin_primes.append((prime_numbers[i], False))
    return twin_primes

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True
