  // Count the number of occurrences of each digit in the array
  for (const element of arr) {
    const digits = getDigits(element, numDigits);
    for (let i = 0; i < numDigits; i++) {
      counts[i][digits[i]]++;
    }
  }

  // Sort the array using the count arrays
  const sortedArr = [];
  for (const digit of counts) {
    const currentCounts = digit.filter(count => count > 0);
    for (const element of arr) {
      if (currentCounts[getDigits(element, numDigits)[i]]) {
        sortedArr.push(element);
        delete currentCounts[getDigits(element, numDigits)[i]];
      }
    }
  }

  return sortedArr;
}

function getDigits(n, numDigits) {
  const digits = [];
  for (let i = 0; i < numDigits; i++) {
    digits.unshift((n % 10).toString());
    n = Math.floor(n / 10);
  }
  return digits;
}
```
In this implementation, we first get the maximum value in the array to determine the number of digits in the radix sort. We then create a count array for each digit and fill it with zeroes. We then loop through the array and count the number of occurrences of each digit in the array using the `getDigits` function, which extracts the corresponding digit from the element.

We then use the `counts` arrays to sort the array by iterating over each digit and adding the elements with the highest counts first. We delete the count for the current element after adding it to the sorted array to avoid duplicates.

