        queue.enqueue(1);
        assertEquals(new Integer(1), queue.peek());
    }

    @Test
    public void isEmpty_emptyQueue() {
        PriorityQueue<Integer> queue = new PriorityQueue<>();
        assertTrue(queue.isEmpty());
    }

    @Test
    public void isFull_fullQueue() {
