        for (int i = 0; i < queue.getCapacity(); i++) {
            queue.enqueue(i);
        }
        assertTrue(queue.isFull());
    }

    @Test
    public void size_correctSize() {
        PriorityQueue<Integer> queue = new PriorityQueue<>();
        for (int i = 0; i < 5; i++) {
            queue.enqueue(i);
        }
        assertEquals(5, queue.size());
    }

    @Test
    public void clear_emptyQueue() {
        PriorityQueue<Integer> queue = new PriorityQueue<>();
        for (int i = 0; i < 5; i++) {
            queue.enqueue(i);
        }
        queue.clear();
        assertTrue(queue.isEmpty());
    }
}
```
These test cases cover different aspects of the `PriorityQueue` class and ensure that it is functioning as expected.

