        video = VideoFileClip(self.filename + ".mp4").set_duration(duration)
        video.write_videofile(f"{self.filename}.{self.video_format}")
        return video

    def zoom_in(self, level):
        if level > self.max_zoom_level:
            raise ValueError("Zoom level exceeds maximum")
        self.zoom_level += level

    def zoom_out(self, level):
        if level < self.min_zoom_level:
            raise ValueError("Zoom level exceeds minimum")
        self.zoom_level -= level

    def apply_filter(self, filter_type):
        if filter_type not in ["grayscale", "blur", "sharpen"]:
            raise ValueError("Unsupported filter type")
        if self.image_data is not None:
            image = Image.fromarray(self.image_data)
            if filter_type == "grayscale":
                image = image.convert("L")
            elif filter_type == "blur":
                image = image.filter(ImageFilter.BLUR)
            elif filter_type == "sharpen":
                image = image.filter(ImageFilter.SHARPEN)
            self.image_data = np.array(image)
        else:
