class Solution {
    public String shortestPalindrome(String s) {
        StringBuilder sb = new StringBuilder(s);
        int n = sb.length();
        for (int i = 0; i < n; i++) {
            if (sb.charAt(i) == sb.charAt(n - i - 1)) continue;
            sb.setCharAt(i, sb.charAt(n - i - 1));
