Here is an example of how you can extract SMTP data from a message using Go:
```
package main

import (
	"fmt"
	"net/smtp"
)

func main() {
	// Create an SMTP client
	client := smtp.Client{
		Host: "your_smtp_server",
		Port: 25,
	}

	// Connect to the SMTP server
	err := client.Connect(nil)
	if err != nil {
		fmt.Println("Error connecting to SMTP server:", err)
		return
	}

	// Log in to the SMTP server
	err = client.Login(nil, "your_username", "your_password")
	if err != nil {
		fmt.Println("Error logging in to SMTP server:", err)
		client.Close()
		return
	}

	// Get the message ID of the last received message
	messageID, err := client.GetLastMessageID()
	if err != nil {
		fmt.Println("Error getting last message ID:", err)
		client.Close()
		return
	}

	// Extract the SMTP data from the message
	messageData, err := client.GetMessageData(messageID)
	if err != nil {
		fmt.Println("Error getting message data:", err)
		client.Close()
		return
	}

	// Print the extracted data
	fmt.Printf("SMTP Data:\n%s\n", messageData)

	// Close the SMTP connection
	err = client.Close()
	if err != nil {
		fmt.Println("Error closing SMTP connection:", err)
	}
}
```
This code creates an `smtp.Client` object and connects to an SMTP server using the `Connect` method. It then logs in to the SMTP server using the `Login` method, and retrieves the message ID of the last received message using the `GetLastMessageID` method. Finally, it extracts the SMTP data from the message using the `GetMessageData` method and prints the extracted data to the console. The code then closes the SMTP connection using the `Close` method.

