JavaScript (script.js):
```
// Get references to the form and error message elements
const form = document.getElementById("inputForm");
const successMessage = document.getElementById("successMessage");
const errorMessage = document.getElementById("errorMessage");

// Add event listener to the form's submit event
form.addEventListener("submit", (event) => {
    // Prevent the form from submitting
    event.preventDefault();

    // Get the values of the Name and Email inputs
    const name = document.getElementById("name").value;
    const email = document.getElementById("email").value;

    // Check if both inputs are valid
    if (name && email) {
        // Validate the Email input format
        if (!validateEmail(email)) {
            // Display error message for invalid Email format
            errorMessage.textContent = "Invalid email address format.";
            return;
        }

        // Check if the Email input is unique
        if (isEmailTaken(email)) {
            // Display error message for duplicate Email
            errorMessage.textContent = "Email is already taken.";
            return;
        }

        // Store the Name and Email in local storage
        localStorage.setItem("name", name);
        localStorage.setItem("email", email);

        // Display success message
        successMessage.textContent = "Data successfully saved.";
    } else {
        // Display error message for missing input
        errorMessage.textContent = "Please enter both Name and Email.";
    }
});

// Validate the Email input format
function validateEmail(email) {
    const re = /^(([^<>()[\]\\.,;:\s@"]+(\.[^<>()[\]\\.,;:\s@"]+)*)|(".+"))@((\[[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\])|(([a-zA-Z\-0-9]+\.)+[a-zA-Z]{2,}))$/;
    return re.test(String(email).toLowerCase());
}

// Check if the Email input is unique
function isEmailTaken(email) {
    const storedEmail = localStorage.getItem("email");
    return email === storedEmail;
}

// Get the Name and Email from local storage and display them on the page
const retrieveButton = document.getElementById("retrieveButton");
retrieveButton.addEventListener("click", () => {
    const name = localStorage.getItem("name");
    const email = localStorage.getItem("email");
    if (name && email) {
        successMessage.textContent = `${name} - ${email}`;
    } else {
        errorMessage.textContent = "No data found in local storage.";
    }
});

// Delete the Name and Email from local storage
const deleteButton = document.getElementById("deleteButton");
deleteButton.addEventListener("click", () => {
    localStorage.removeItem("name");
    localStorage.removeItem("email");
    successMessage.textContent = "Data successfully deleted.";
});
