Here is an example of how you can implement the `Song`, `Artist`, and `MusicLibrary` classes in Python:
```python
class Song:
    def __init__(self, title, duration):
        self.title = title
        self.duration = duration

class Artist:
    def __init__(self, name):
        self.name = name

class MusicLibrary:
    def __init__(self):
        self.songs = {}
        self.artists = {}

    def add_song(self, song):
        self.songs[song.title] = song

    def add_artist(self, artist):
        self.artists[artist.name] = artist

    def associate_song_with_artist(self, song, artist):
        if not self.songs.get(song.title) or not self.artists.get(artist.name):
            raise ValueError("Song and/or artist does not exist in the library.")
        self.songs[song.title].artists.append(artist.name)
        self.artists[artist.name].songs.append(song.title)

    def retrieve_songs_by_artist(self, artist):
        if not self.artists.get(artist.name):
            raise ValueError("Artist does not exist in the library.")
        return [song for song in self.songs.values() if artist.name in song.artists]
```
