```
class ChatService {

    // URL for sending chat messages to the server
    let messageUrl = "https://yourserver.com/chat"

    // Send a chat message to the server
    func sendChatMessage(senderName: String, messageText: String) {
        guard let url = URL(string: messageUrl) else { return }

        var request = URLRequest(url: url)
        request.httpMethod = "POST"

        // Set the HTTP headers and body for the request
        request.addValue("application/json", forHTTPHeaderField: "Content-Type")
        request.httpBody = try? JSONSerialization.data(withJSONObject: ["senderName": senderName, "messageText": messageText], options: [])

        // Send the request to the server and handle the response
        let task = URLSession.shared.dataTask(with: request) { (data, response, error) in
            guard let data = data else { return }

            do {
                // Try to parse the JSON response from the server
                let decoder = JSONDecoder()
                let chatMessage = try decoder.decode(ChatMessage.self, from: data)

                // Add the new chat message to the list of messages
                self.messages.append(chatMessage)
            } catch {
                print("Error parsing JSON response: \(error)")
            }
        }

        task.resume()
    }

    // Retrieve the latest chat messages from the server
    func retrieveLatestMessages() -> [ChatMessage] {
        guard let url = URL(string: messageUrl) else { return [] }

        var request = URLRequest(url: url)
        request.httpMethod = "GET"

        // Send the request to the server and handle the response
        let task = URLSession.shared.dataTask(with: request) { (data, response, error) in
            guard let data = data else { return [] }

            do {
                // Try to parse the JSON response from the server
                let decoder = JSONDecoder()
                let chatMessages = try decoder.decode([ChatMessage].self, from: data)

                // Return the list of chat messages
                return chatMessages
            } catch {
                print("Error parsing JSON response: \(error)")
            }

            return []
        }

        task.resume()
    }
}
```
