// Function to check if a given string is a palindrome
function isPalindrome(str) {
  // Convert the input string to lowercase
  str = str.toLowerCase();

  // Check if the input string is empty or null
  if (str === "") return false;

  // Get the length of the input string
  let len = str.length;

  // Initialize a variable to keep track of whether the string is palindromic
  let isPalindrome = true;

  // Loop through each character in the input string
  for (let i = 0; i < len / 2; i++) {
    // Check if the current character is the same as the corresponding character in the opposite end of the string
    if (str[i] !== str[len - i - 1]) {
      // If the characters are not the same, set isPalindrome to false and break out of the loop
      isPalindrome = false;
      break;
    }
  }

  return isPalindrome;
}
```
