def binary_search(arr, target):
    leftIndex = 0
    rightIndex = len(arr) - 1

    while leftIndex <= rightIndex:
        mid = (leftIndex + rightIndex) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            leftIndex = mid + 1
        else:
            rightIndex = mid - 1

    return -1
```
