class RuleDaoServices extends AbstractDaoServices {

    // Constructor
    public RuleDaoServices(DataSource dataSource) {
        super(dataSource);
    }

    // CRUD operations for rules

    /**
     * Creates a new rule in the database.
     * @param rule The rule to create.
     */
    public void createRule(Rule rule) {
        String sql = "INSERT INTO rules (name, description, condition, action) VALUES (?, ?, ?, ?)";
        try (Connection connection = dataSource.getConnection();
             PreparedStatement statement = connection.prepareStatement(sql)) {
            statement.setString(1, rule.getName());
            statement.setString(2, rule.getDescription());
            statement.setString(3, rule.getCondition());
            statement.setString(4, rule.getAction());
            statement.executeUpdate();
        } catch (SQLException e) {
            throw new RuntimeException("Error creating rule", e);
        }
    }

    /**
     * Reads a rule from the database.
     * @param id The ID of the rule to read.
     * @return The requested rule, or null if not found.
     */
    public Rule readRule(int id) {
        String sql = "SELECT * FROM rules WHERE id = ?";
        try (Connection connection = dataSource.getConnection();
             PreparedStatement statement = connection.prepareStatement(sql)) {
            statement.setInt(1, id);
            ResultSet resultSet = statement.executeQuery();
            if (resultSet.next()) {
                return new Rule(id, resultSet.getString("name"), resultSet.getString("description"),
                        resultSet.getString("condition"), resultSet.getString("action"));
            }
            return null;
        } catch (SQLException e) {
            throw new RuntimeException("Error reading rule", e);
        }
    }

    /**
     * Updates an existing rule in the database.
     * @param rule The updated rule.
     */
    public void updateRule(Rule rule) {
        String sql = "UPDATE rules SET name = ?, description = ?, condition = ?, action = ? WHERE id = ?";
        try (Connection connection = dataSource.getConnection();
             PreparedStatement statement = connection.prepareStatement(sql)) {
            statement.setString(1, rule.getName());
            statement.setString(2, rule.getDescription());
            statement.setString(3, rule.getCondition());
            statement.setString(4, rule.getAction());
            statement.setInt(5, rule.getId());
            statement.executeUpdate();
        } catch (SQLException e) {
            throw new RuntimeException("Error updating rule", e);
        }
    }

    /**
     * Deletes a rule from the database.
     * @param id The ID of the rule to delete.
     */
    public void deleteRule(int id) {
        String sql = "DELETE FROM rules WHERE id = ?";
        try (Connection connection = dataSource.getConnection();
             PreparedStatement statement = connection.prepareStatement(sql)) {
            statement.setInt(1, id);
            statement.executeUpdate();
        } catch (SQLException e) {
            throw new RuntimeException("Error deleting rule", e);
        }
    }
}

