def is_palindrome(string):
    # Convert the input string to lowercase
    string = string.lower()

    # Iterate over the characters in the string and count the number of occurrences of each character
    char_counts = {}
    for char in string:
        if char not in char_counts:
            char_counts[char] = 1
        else:
            char_counts[char] += 1

    # Check if the number of occurrences of each character is even
    for char, count in char_counts.items():
        if count % 2 != 0:
            return False

    return True
